// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Pattern".

This little dance could also be seen as a pattern of defense,
both from the way it is performed, and from the year 2026.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2914010/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define T time
#define R resolution
#define MN min(R.x,R.y)
#define S smoothstep
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin((a)*2.8+vec3(1.5,2,3)))
// Complex analysis formulas
#define cdiv(a,b) vec2(a.x*b.x+a.y*b.y,a.y*b.x-a.x*b.y)/dot(b,b)
#define cmul(a,b) vec2(a.x*b.x-a.y*b.y,a.y*b.x+a.x*b.y)
// Smooth abs
#define sabs(a) smin(a,-a,-.025)
// Stretching out the figure - values lower than 2 result in artifacts
#define D 10.
#define TAU radians(360.)
// Animation time - repeat every 30 secs
#define TT mod(T,30.)
// Smooth minimum
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// Complex square root
vec2 csqrt(vec2 z) {
	float s=length(z);
	vec2 r=sqrt(max(.5*vec2(s+z.x,s-z.x),.0));
	return z.y<.0?r:vec2(r.x,-r.y);
}
// Circular domain repetition
vec2 pmod(vec2 p, float n) {
	float a=atan(p.x,p.y), b=TAU/n;
	return p*rot(round(a/b)*b);
}
// Main scene
vec3 scene(vec2 uv) {
	float t=2.8*T; t=sin(t)*cos(t);
	// 3rd figure
	if (TT>15.) uv.x=abs(uv.x)-.4;
	uv*=rot(T-t*.2);
	// 2nd figure
	if (TT>7.5) uv.x=sabs(uv.x)-.12;
	uv*=rot(-(2.*exp(cos(sin(T)))));
	// 1st figure
	uv.x=sabs(uv.x)-.1;
	vec2
	a=vec2(uv.x,uv.y+D),
	b=vec2(uv.x,uv.y-D),
	// the shape of the figure
	q=cdiv((a+b),(a/b));
	vec2 st=2.*(FC/R)-1.;
	// the resulting vector is used to
	// add some unnecessary drama
	st=cmul(st,st.yx);
	st=csqrt(st);
	st=abs(st)+atan(q.y,q.x)/TAU;
	float k=min(st.x,st.y);
	return hue(k);
}
vec3 render(vec2 uv) {
	if (TT>15.) uv*=2.;
	// 4th figure
	if (TT>22.5) {
		uv=pmod(uv,3.);
		uv.y-=.5;
	}
	// add some white noise to give it a grainy look
	float k=fract(sin(dot(uv,vec2(12.9898,78.233)))*345678.);
	vec3 col=scene(uv)*mix(.9,1.,k);
	// emphasize blue and red
	col*=vec3(1,.2,.8);
	// color grade - smoothen the gradients
	col/=1.+exp(-S(-.5,1.5,col));
	return col;
}
// Anti alias
#define AA
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=render(uv);
	// Anti alias loop
	#ifdef AA
	for (float x=.0; x<=1.; x++) {
		for (float y=.0; y<=1.; y++)
			col+=render(uv+(vec2(x,y)-.5)/R);
	}
	col/=5.;
	#endif
	O=vec4(col,1);
}

